118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        // Normalize the address up front so every downstream use (the required-field check,
122	        // household-duplicate detection, the shared household id and the stored/returned value)
123	        // works from the same canonical form.
124	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
125	        List<String> missingFields = new ArrayList<>();
126	        if (isBlank(ownerFieldsDto.getFirstName())) {
127	            missingFields.add("firstName");
128	        }
129	        if (isBlank(ownerFieldsDto.getLastName())) {
130	            missingFields.add("lastName");
131	        }
132	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
133	        if (isBlank(normalizedAddress)) {
134	            missingFields.add("address");
135	        }
136	        if (isBlank(ownerFieldsDto.getCity())) {
137	            missingFields.add("city");
138	        }
139	        if (isBlank(ownerFieldsDto.getTelephone())) {
140	            missingFields.add("telephone");
141	        }
142	        if (!missingFields.isEmpty()) {
143	            throw new InvalidOwnerFieldsException(missingFields);
144	        }
145	        // A supplied registration date may not lie in the future: reject with 400 when the caller
146	        // provides a date later than the server's current date. Checked against the raw supplied value
147	        // (before any business-day adjustment) so a future date is never silently accepted.
148	        if (ownerFieldsDto.getRegistrationDate() != null
149	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
150	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
151	        }
152	        // Determine the effective registration date up front so every downstream use (the daily
153	        // create-limit, the stored value and anything derived from it such as the membership number's
154	        // year segment) works from the same business-day-adjusted date. The effective date is the
155	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
156	        // forward to the following Monday.
157	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
158	            ? ownerFieldsDto.getRegistrationDate()
159	            : LocalDate.now();
160	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
161	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
162	        // already carry this adjusted business day's registration date, no further owners may be
163	        // created for that day.
164	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
165	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
166	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
167	        }
168	        // Flag a bulk signup once more than 80 owners have already been created for this
169	        // business day, sharing the same daily accumulation path as the create-limit rule above.
170	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
171	        // Reject the request when the owner's city is already full: a city that already holds the
172	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
173	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
174	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
175	        }
176	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
177	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
178	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
179	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
180	        // Normalize the telephone into E.164 form; a number that cannot form a valid
181	        // E.164 value is rejected with a 400.
182	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
183	        // Email is optional; when present it must be a syntactically valid address and is
184	        // stored lower-cased. An invalid address is rejected with a 400.
185	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
186	        // Derive the household id up front. It is a deterministic function of the normalized last name
187	        // and the postcode, so owners sharing a last name and postcode independently derive the same
188	        // value and are the same household. It is always computed (never null), regardless of whether
189	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
190	        // duplicate block below.
191	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
192	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
193	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
194	        // All duplicate detection is consolidated into a single derived identity key:
195	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
196	        // part of the key, two members of the same household (same householdId) with different
197	        // telephones have different keys and are both allowed; only an exact whole-key match is a
198	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
199	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
200	        boolean identityInUse = this.clinicService.findAllOwners().stream()
201	            .anyMatch(existing -> identityKey.equals(
202	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
203	        if (identityInUse) {
204	            throw new DuplicateOwnerIdentityException(identityKey);
205	        }
206	        // Because the household is keyed on (last name, postcode), any existing owner carrying this
207	        // computed household id is already a member of this household. A second such owner is rejected
208	        // as a household duplicate (409) unless the caller declares 'sharesHousehold', which bypasses
209	        // the block and admits the owner as a declared household member.
210	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
211	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
212	        if (householdMemberExists && !sharesHousehold) {
213	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), normalizedAddress);
214	        }
215	        HttpHeaders headers = new HttpHeaders();
216	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
217	        owner.setAddress(normalizedAddress);
218	        owner.setTelephone(normalizedTelephone);
219	        owner.setEmail(normalizedEmail);
220	        owner.setHouseholdId(householdId);
221	        // Record how many existing owners (before this create) share this owner's first and last
222	        // name, compared case-insensitively. Computed against the current owners so the new owner
223	        // itself is never counted.
224	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
225	        // Record the size of this owner's household (owners sharing the same householdId) after this
226	        // create: the existing members already stamped with the shared identifier plus this new
227	        // owner. An owner not admitted into any household is a household of one.
228	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
229	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
230	        owner.setBulkSignupWarning(bulkSignupWarning);
231	        // Store the business-day-adjusted effective registration date computed above. This defaults
232	        // to the server's current date when none was supplied and rolls any weekend date forward to
233	        // the following Monday, so everything derived from it (e.g. the membership number's year
234	        // segment) uses the adjusted date.
235	        owner.setRegistrationDate(effectiveRegistrationDate);
236	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
237	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
238	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
239	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
240	        owner.setCustomerCode(customerCode(
241	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName()));
242	        // Soft-match detection: an owner that cleared the hard-duplicate checks above may still
243	        // resemble an existing owner when it shares that owner's last name and postcode but carries a
244	        // different telephone. A declared household member ('sharesHousehold') is never a suspected
245	        // duplicate, so it is exempt; any other owner reaching here shares no household with an
246	        // existing owner (a household match without 'sharesHousehold' was already rejected above).
247	        // Flag a matched owner as a possible duplicate, recording its id; otherwise the flag is false
248	        // with no matched id.
249	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
250	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
251	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
252	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
253	        this.clinicService.saveOwner(owner);
254	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
255	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
256	        // customer code, the effective registration date and the numeric membership level.
257	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
258	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
259	        headers.setLocation(UriComponentsBuilder.newInstance()
260	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
261	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
262	    }
