264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner == null) {
269	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	        }
271	        currentOwner.setAddress(ownerFieldsDto.getAddress());
272	        currentOwner.setCity(ownerFieldsDto.getCity());
273	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
274	        currentOwner.setLastName(ownerFieldsDto.getLastName());
275	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
276	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
277	        this.clinicService.saveOwner(currentOwner);
278	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
279	    }
