358	    private static boolean isBlank(String value) {
359	        return value == null || value.trim().isEmpty();
360	    }
361	
362	    /**
363	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
364	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
365	     * compared case-insensitively with collapsed whitespace.
366	     */
367	    private static String collapse(String value) {
368	        if (value == null) {
369	            return "";
370	        }
371	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
372	    }
373	
374	    /**
375	     * Common street-type abbreviations expanded during address normalization.
376	     */
377	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
378	        "ST", "STREET",
379	        "RD", "ROAD",
380	        "AVE", "AVENUE");
381	
382	    /**
383	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
384	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
385	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
386	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
387	     * address maps to itself.
388	     */
389	    private static String normalizeAddress(String value) {
390	        if (value == null) {
391	            return "";
392	        }
393	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
394	        if (collapsed.isEmpty()) {
395	            return "";
396	        }
397	        String[] tokens = collapsed.split(" ");
398	        StringBuilder sb = new StringBuilder(collapsed.length());
399	        for (int i = 0; i < tokens.length; i++) {
400	            if (i > 0) {
401	                sb.append(' ');
402	            }
403	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
404	        }
405	        return sb.toString();
406	    }
407	
408	    /**
409	     * Derive the stable household identifier shared by owners with the same normalized last name
410	     * and postcode. It is a deterministic function of those two values, so every member of a
411	     * household independently derives the same identifier: the first 12 upper-case hex characters
412	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
413	     * an empty segment.
414	     */
415	    private static String householdId(String normalizedLastName, String postcode) {
416	        try {
417	            byte[] digest = MessageDigest.getInstance("SHA-256")
418	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
419	                    .getBytes(StandardCharsets.UTF_8));
420	            StringBuilder sb = new StringBuilder(digest.length * 2);
421	            for (byte b : digest) {
422	                sb.append(String.format("%02x", b));
423	            }
424	            return sb.substring(0, 12).toUpperCase();
425	        }
426	        catch (NoSuchAlgorithmException e) {
427	            throw new IllegalStateException("SHA-256 not available", e);
428	        }
429	    }
430	
431	    /**
432	     * Derive the identity key into which all duplicate detection is consolidated:
433	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
434	     * household id contributes an empty segment. Two owners are duplicates only when their whole
435	     * identity keys are equal.
436	     */
437	    private static String identityKey(String telephone, String email, String householdId) {
438	        return (telephone == null ? "" : telephone)
439	            + "|" + (email == null ? "" : email)
440	            + "|" + (householdId == null ? "" : householdId);
441	    }
442	
443	    /**
444	     * Count the existing owners that share the given first and last name, compared
445	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
446	     * namesakes that already existed at creation time (the new owner itself is not included).
447	     */
448	    private int countNamesakes(String firstName, String lastName) {
449	        return (int) this.clinicService.findAllOwners().stream()
450	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
451	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
452	                && existing.getLastName().equalsIgnoreCase(lastName))
453	            .count();
454	    }
455	
456	    /**
457	     * Count the existing owners that already belong to the given household (i.e. carry the same
458	     * non-null householdId). Called after any existing members have been backfilled with the shared
459	     * identifier but before the new owner is saved, so the returned value reflects the members that
460	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
461	     * new owner is not part of any household ({@code householdId} is null).
462	     */
463	    private int countHouseholdMembers(String householdId) {
464	        if (householdId == null) {
465	            return 0;
466	        }
467	        return (int) this.clinicService.findAllOwners().stream()
468	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
469	            .count();
470	    }
471	
472	    /**
473	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
474	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
475	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
476	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
477	     * including when the new owner has no last name or postcode, since a shared postcode is required
478	     * to match.
479	     */
480	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
481	        if (isBlank(lastName) || isBlank(postcode)) {
482	            return null;
483	        }
484	        return this.clinicService.findAllOwners().stream()
485	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
486	            .filter(existing -> postcode.equals(existing.getPostcode()))
487	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
488	            .min(java.util.Comparator.comparing(Owner::getId))
489	            .orElse(null);
490	    }
491	
492	    /**
493	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
494	     * request to create another owner in it is rejected as a conflict.
495	     */
496	    private static final int MAX_OWNERS_PER_CITY = 50;
497	
498	    /**
499	     * Count the existing owners registered in the given city, compared case-insensitively (as in
500	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
501	     * reflects the owners that already existed at creation time.
502	     */
503	    private int countOwnersInCity(String city) {
504	        return (int) this.clinicService.findAllOwners().stream()
505	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
506	            .count();
507	    }
508	
509	    /**
510	     * The maximum number of owners that may be created on a single day. Once this many owners
511	     * already carry a given day's registration date, a request to create another owner that day is
512	     * rejected with a 429.
513	     */
514	    private static final int MAX_OWNERS_PER_DAY = 100;
515	
516	    /**
517	     * The number of owners that may be created on a single day before the bulk-signup warning is
518	     * flagged. Once more than this many owners already carry a given day's registration date, a
519	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
520	     */
521	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
522	
523	    /**
524	     * Count the existing owners whose registration date is the given day. Called before the new
525	     * owner is saved, so the returned value reflects the owners that already existed at creation
526	     * time.
527	     */
528	    private int countOwnersRegisteredOn(LocalDate date) {
529	        return (int) this.clinicService.findAllOwners().stream()
530	            .filter(existing -> date.equals(existing.getRegistrationDate()))
531	            .count();
532	    }
533	
534	    /**
535	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
536	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
537	     * supplied or defaulted) always falls on a business day.
538	     */
539	    private static LocalDate toBusinessDay(LocalDate date) {
540	        return switch (date.getDayOfWeek()) {
541	            case SATURDAY -> date.plusDays(2);
542	            case SUNDAY -> date.plusDays(1);
543	            default -> date;
544	        };
545	    }
546	
547	    /**
548	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
549	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
550	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
551	     */
552	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
553	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
554	    }
555	
556	    /**
557	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
558	     */
559	    private static String hash8(String input) {
560	        try {
561	            byte[] digest = MessageDigest.getInstance("SHA-256")
562	                .digest(input.getBytes(StandardCharsets.UTF_8));
563	            StringBuilder sb = new StringBuilder(digest.length * 2);
564	            for (byte b : digest) {
565	                sb.append(String.format("%02x", b));
566	            }
567	            return sb.substring(0, 8).toUpperCase();
568	        }
569	        catch (NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 not available", e);
571	        }
572	    }
573	
574	    /**
575	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
576	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
577	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
578	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
579	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
580	     * always agree.
581	     */
582	    private static String deriveRegion(String postcode, String city) {
583	        if (postcode != null && postcode.matches("\\d{4}")) {
584	            int value = Integer.parseInt(postcode);
585	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
586	                int[] range = entry.getValue();
587	                if (value >= range[0] && value <= range[1]) {
588	                    return entry.getKey();
589	                }
590	            }
591	        }
592	        if (city == null) {
593	            return "UNKNOWN";
594	        }
595	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
596	    }
597	
598	    /**
599	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
600	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
601	     * and accepts any 4-digit postcode.
602	     */
603	    private static final Map<String, String> CITY_REGION = Map.of(
604	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
605	
606	    /**
607	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
608	     * Each entry is a two-element {@code {low, high}} array.
609	     */
610	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
611	        "NSW", new int[] {2000, 2099},
612	        "VIC", new int[] {3000, 3099},
613	        "QLD", new int[] {4000, 4099});
614	
615	    /**
616	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
617	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
618	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
619	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
620	     * 4-digit postcode. A malformed or out-of-range postcode throws an
621	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
622	     */
623	    private static void validatePostcode(String city, String postcode) {
624	        if (postcode == null || postcode.isEmpty()) {
625	            return;
626	        }
627	        if (!postcode.matches("\\d{4}")) {
628	            throw new InvalidOwnerFieldsException(List.of("postcode"));
629	        }
630	        String region = city == null ? null : CITY_REGION.get(city);
631	        if (region == null) {
632	            return;
633	        }
634	        int[] range = REGION_POSTCODES.get(region);
635	        int value = Integer.parseInt(postcode);
636	        if (value < range[0] || value > range[1]) {
637	            throw new InvalidOwnerFieldsException(List.of("postcode"));
638	        }
639	    }
640	
641	    /**
642	     * Required national-number length for each E.164 country calling code we validate: a
643	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
644	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
645	     */
646	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
647	        "1", 10,
648	        "61", 9);
649	
650	    /**
651	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
652	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
653	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
654	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
655	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
656	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
657	     * rejected with a 400.
658	     */
659	    private static String toE164(String raw) {
660	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
661	        boolean hasCountryCode = cleaned.startsWith("+");
662	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
663	        if (!digits.matches("\\d+")) {
664	            throw new InvalidOwnerFieldsException(List.of("telephone"));
665	        }
666	        if (!hasCountryCode) {
667	            if (digits.startsWith("0")) {
668	                digits = digits.substring(1);
669	            }
670	            digits = "61" + digits;
671	        }
672	        if (digits.length() < 8 || digits.length() > 15) {
673	            throw new InvalidOwnerFieldsException(List.of("telephone"));
674	        }
675	        // For a recognised country code, the national number (the digits after the code) must be
676	        // exactly the expected length for that country. Match the longest known code so a shorter
677	        // code that is a prefix of another cannot mask it.
678	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
679	            if (digits.length() <= codeLength) {
680	                continue;
681	            }
682	            String countryCode = digits.substring(0, codeLength);
683	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
684	            if (requiredNationalLength != null) {
685	                if (digits.length() - codeLength != requiredNationalLength) {
686	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
687	                }
688	                break;
689	            }
690	        }
691	        return "+" + digits;
692	    }
693	
694	    /**
695	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
696	     * and a domain with at least one dot-separated label, none of which contain whitespace or
697	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
698	     */
699	    private static final Pattern EMAIL_PATTERN =
700	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
701	
702	    /**
703	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
704	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
705	     */
706	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
707	        "mailinator.com", "tempmail.com", "guerrillamail.com");
708	
709	    /**
710	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
711	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
712	     * domain is not on the disposable-domain blocklist, otherwise an
713	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
714	     * address is returned lower-cased.
715	     */
716	    private static String normalizeEmail(String email) {
717	        if (email == null || email.isEmpty()) {
718	            return null;
719	        }
720	        String trimmed = email.trim();
721	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
722	            throw new InvalidOwnerFieldsException(List.of("email"));
723	        }
724	        String normalized = trimmed.toLowerCase();
725	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
726	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
727	            throw new InvalidOwnerFieldsException(List.of("email"));
728	        }
729	        return normalized;
730	    }
731	}
