24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	        expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "membershipNumber",
29	        expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	        expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel",
33	        expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality",
35	        expression = "java(locality(owner))")
36	    @Mapping(target = "contactPreference",
37	        expression = "java(contactPreference(owner))")
38	    @Mapping(target = "identityKey",
39	        expression = "java(identityKey(owner))")
40	    @Mapping(target = "checkDigit",
41	        expression = "java(checkDigit(owner))")
42	    @Mapping(target = "ageBand",
43	        expression = "java(ageBand(owner))")
44	    @Mapping(target = "sharesHousehold", ignore = true)
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
49	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
50	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
51	     * so owners without a birth date serialize cleanly.
52	     */
53	    default String ageBand(Owner owner) {
54	        java.time.LocalDate birthDate = owner.getBirthDate();
55	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
56	        if (birthDate == null || registrationDate == null) {
57	            return null;
58	        }
59	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
60	        if (age < 18) {
61	            return "MINOR";
62	        }
63	        if (age < 65) {
64	            return "ADULT";
65	        }
66	        return "SENIOR";
67	    }
68	
69	    /**
70	     * The E.164 country calling codes whose split from the national number is recognised when
71	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
72	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
73	     */
74	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
75	
76	    /**
77	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
78	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
79	     * country code is split off using the recognised calling codes; when none matches, a single-digit
80	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
81	     * Returns the stored value unchanged when it is null or not in E.164 form.
82	     */
83	    default String telephoneDisplay(Owner owner) {
84	        String telephone = owner.getTelephone();
85	        if (telephone == null || !telephone.startsWith("+")) {
86	            return telephone;
87	        }
88	        String digits = telephone.substring(1);
89	        if (!digits.matches("\\d+")) {
90	            return telephone;
91	        }
92	        String countryCode = digits.substring(0, 1);
93	        String national = digits.substring(1);
94	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
95	            String candidate = digits.substring(0, codeLength);
96	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
97	                countryCode = candidate;
98	                national = digits.substring(codeLength);
99	                break;
100	            }
101	        }
102	        StringBuilder grouped = new StringBuilder();
103	        for (int i = 0; i < national.length(); i++) {
104	            if (i > 0 && i % 3 == 0) {
105	                grouped.append(' ');
106	            }
107	            grouped.append(national.charAt(i));
108	        }
109	        return "+" + countryCode + " " + grouped;
110	    }
111	
112	    /**
113	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
114	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
115	     * serialize cleanly.
116	     */
117	    default Integer checkDigit(Owner owner) {
118	        String customerCode = owner.getCustomerCode();
119	        if (customerCode == null) {
120	            return null;
121	        }
122	        int sum = 0;
123	        boolean dbl = true;
124	        for (int i = customerCode.length() - 1; i >= 0; i--) {
125	            char c = customerCode.charAt(i);
126	            if (c < '0' || c > '9') {
127	                continue;
128	            }
129	            int d = c - '0';
130	            if (dbl) {
131	                d *= 2;
132	                if (d > 9) {
133	                    d -= 9;
134	                }
135	            }
136	            sum += d;
137	            dbl = !dbl;
138	        }
139	        return (10 - (sum % 10)) % 10;
140	    }
141	
142	    /**
143	     * Derive the owner's identity key, the single value into which all duplicate detection is
144	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
145	     * owners are duplicates only when their whole identity keys are equal. A null email or
146	     * householdId contributes an empty segment.
147	     */
148	    default String identityKey(Owner owner) {
149	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
150	        String email = owner.getEmail() == null ? "" : owner.getEmail();
151	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
152	        return telephone + "|" + email + "|" + householdId;
153	    }
154	
155	    /**
156	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
157	     * otherwise 'PHONE'.
158	     */
159	    default String contactPreference(Owner owner) {
160	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
161	        return hasEmail ? "EMAIL" : "PHONE";
162	    }
163	
164	    /**
165	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
166	     * the last two digits of the registrationDate year. Returns null when either source field is
167	     * absent so owners without an assigned code or registration date serialize cleanly.
168	     */
169	    default String membershipNumber(Owner owner) {
170	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
171	            return null;
172	        }
173	        return String.format("%s-M%02d", owner.getCustomerCode(),
174	            owner.getRegistrationDate().getYear() % 100);
175	    }
176	
177	    /**
178	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
179	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
180	     * (householdSize); add 3 for tenure of more than 365 days, measured from the registrationDate to
181	     * the current date. Because a newly created owner has zero tenure, a new owner never earns the
182	     * tenure points.
183	     */
184	    default Integer membershipPoints(Owner owner) {
185	        int points = 0;
186	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
187	        if (hasEmail) {
188	            points += 2;
189	        }
190	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
191	        if (noNamesakes) {
192	            points += 1;
193	        }
194	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
195	            points += 2;
196	        }
197	        if (owner.getRegistrationDate() != null && java.time.temporal.ChronoUnit.DAYS.between(
198	                owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
199	            points += 3;
200	        }
201	        return points;
202	    }
203	
204	    /**
205	     * Determine the owner's numeric membership level, derived from membershipPoints: 1 for 0-1
206	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
207	     */
208	    default Integer membershipLevel(Owner owner) {
209	        int points = membershipPoints(owner);
210	        if (points <= 1) {
211	            return 1;
212	        }
213	        if (points <= 3) {
214	            return 2;
215	        }
216	        if (points <= 5) {
217	            return 3;
218	        }
219	        return 4;
220	    }
221	
222	    /**
223	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
224	     * or falls in no known range.
225	     */
226	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
227	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
228	
229	    /**
230	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
231	     * QLD 4000-4099.
232	     */
233	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
234	        "NSW", new int[] {2000, 2099},
235	        "VIC", new int[] {3000, 3099},
236	        "QLD", new int[] {4000, 4099});
237	
238	    /**
239	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
240	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
241	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
242	     * absent or in no known range. Returns 'UNKNOWN' when neither source resolves a region.
243	     */
244	    default String locality(Owner owner) {
245	        String postcode = owner.getPostcode();
246	        if (postcode != null && postcode.matches("\\d{4}")) {
247	            int value = Integer.parseInt(postcode);
248	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
249	                int[] range = entry.getValue();
250	                if (value >= range[0] && value <= range[1]) {
251	                    return entry.getKey();
252	                }
253	            }
254	        }
255	        String city = owner.getCity();
256	        if (city == null) {
257	            return "UNKNOWN";
258	        }
259	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
260	    }
